def sha256_file(path: Path) -> str:
    return sha256(path.read_bytes()).hexdigest()


def verify_osr013_contract() -> None:
    if not SOURCE_OSR013.is_file():
        raise FileNotFoundError(
            f"Actual OSR-013 module missing: {SOURCE_OSR013}"
        )

    source = SOURCE_OSR013.read_text(encoding="utf-8")
    required = (
        'ENGINE_ID = "OSR-013"',
        "verify_deterministic_callable_binding_execution_result_record",
        "DeterministicCallableBindingExecutionResultRecord",
        "result_hash",
        "envelope_verified",
        "exact_envelope_hash_scope_preserved",
        "execution_attempted",
        "callable_invocation_performed",
        "reasoning_execution_performed",
        "read_only",
        "qseries_execution_performed",
        "order_creation_performed",
        "funds_movement_performed",
        "portfolio_mutation_performed",
    )
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(
            "Actual OSR-013 contract mismatch; missing: "
            + ", ".join(missing)
        )

    ast.parse(source, filename=str(SOURCE_OSR013))
    print(
        "[OK] Actual OSR-013 deterministic execution-result "
        "contract verified"
    )


def write_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def append_export(path: Path, line: str) -> None:
    existing = path.read_text(encoding="utf-8") if path.exists() else ""
    if line in existing.splitlines():
        print(f"[OK] PACKAGE EXPORT PRESENT: {path.resolve()}")
        return
    if existing and not existing.endswith("\n"):
        existing += "\n"
    path.write_text(existing + line + "\n", encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] PACKAGE UPDATED: {path.resolve()}")


def main() -> int:
    print("========================================")
    print(" OSR-014 INSTALLER")
    print(" ORACLE SCIENTIFIC REASONING RUNTIME")
    print(" TERMINAL CERTIFICATION AND FREEZE GATE")
    print("========================================")

    if not (ROOT / "qseries_v2").is_dir():
        raise SystemExit(
            "[ERROR] Run this installer from the kalshi-qss-bot repository root."
        )

    verify_osr013_contract()
    protected_hash = sha256_file(SOURCE_OSR013)

    write_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_replacement(TEST, TEST_SOURCE)
    append_export(
        PACKAGE_INIT,
        "from .oracle_scientific_reasoning_runtime_terminal_certification_and_freeze_gate import *",
    )

    if sha256_file(SOURCE_OSR013) != protected_hash:
        raise RuntimeError("Protected OSR-013 module changed during installation")
    print("[PASS] Protected OSR-013 module unchanged")

    completed = subprocess.run(
        [sys.executable, str(TEST)],
        cwd=str(ROOT),
        check=False,
    )
    if completed.returncode:
        raise SystemExit(completed.returncode)

    if sha256_file(SOURCE_OSR013) != protected_hash:
        raise RuntimeError("Protected OSR-013 module changed during testing")

